-- ==================== LOGICA ANTI DOUBLE PARRY INTEGRATA ====================
local function checkAndParry(ball, parry_accuracy, distance, isTraining)
    if not ball then return end

    local antiDoubleEnabled = isTraining and Config.TrainingAntiDoubleParry or Config.AntiDoubleParry

    -- 1. Reset del flag di parry appena il target della palla cambia
    if ball ~= lastTrackedBall then
        lastTrackedBall = ball
        if currentTargetSignal then
            currentTargetSignal:Disconnect()
            currentTargetSignal = nil
        end
        pcall(function()
            currentTargetSignal = ball:GetAttributeChangedSignal(zPxZTHEHprVwhcApSbrpeuCGNLVPIdqKxsCxRMQMPonldYdhMHcQtzCJLgiVuPZKMeLi({12180,10185,11970,10815,10605,12180})):Connect(function()
                parried = false
            end)
        end)
    end

    -- 2. Se è già stato eseguito un parry per questo turno/target, interrompe la funzione
    if antiDoubleEnabled and parried then
        return
    end

    local ball_target = ball:GetAttribute(zPxZTHEHprVwhcApSbrpeuCGNLVPIdqKxsCxRMQMPonldYdhMHcQtzCJLgiVuPZKMeLi({12180,10185,11970,10815,10605,12180})) or ball:GetAttribute(zPxZTHEHprVwhcApSbrpeuCGNLVPIdqKxsCxRMQMPonldYdhMHcQtzCJLgiVuPZKMeLi({8820,10185,11970,10815,10605,12180}))
    local isTargetingMe = (ball_target == local_player.Name) or (isTraining)

